sksl:
uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float blockSize;
uniform float2 stretch;
uniform float2 offset;
uniform float angle;
uniform float vignette;
uniform float screenSpace;

half4 main(float2 coord) {
    float2 origin = (screenSpace > 0.5 ? screen.xy + screen.zw * 0.5 : size * 0.5) + offset;
    float2 cell = max(blockSize * stretch, float2(1.0));
    float a = radians(angle);
    float c = cos(a);
    float s = sin(a);
    float2 d = coord - origin;
    float2 p = float2(c * d.x + s * d.y, c * d.y - s * d.x) / cell;
    float2 b = floor(p);
    float2 m = (b + 0.5) * cell;
    half4 col = image.eval(origin + float2(c * m.x - s * m.y, s * m.x + c * m.y));
    if (vignette > 0.0 && col.a > 0.001) {
        float2 e = abs(p - b - 0.5) * 2.0;
        half3 un = col.rgb / col.a;
        col.rgb = max(un - half(vignette * (0.04 + 0.08 * dot(e, e))), half3(0.0)) * col.a;
    }
    return col;
}
